-- Query: SitLunara
-- Type: Select

SELECT Platitori.Nume, Platitori.IDP, Sum(XSolduri.SoldInitial) AS SoldInitial, Sum(XSolduri.SoldPrezenta) AS SoldPrezenta, Sum(XSolduri.SoldPlati) AS SoldPlati, Sum(XSolduri.SoldRetur) AS SoldRetur, [soldprezenta]+[soldinitial]-[soldplati]+[soldretur] AS Sold, IIf([sold]>0,[sold],0) AS SID, IIf([sold]<0,Abs([sold]),0) AS SIC, Sum(CDbl(Nz([SumaPlati],0))) AS Platita, Sum(CDbl(Nz([SumaRetur],0))) AS Retur
FROM (((SELECT Solduri.IDP, Sum(Solduri.SoldInitial) AS SoldInitial, Sum(Solduri.SoldPrezenta) AS SoldPrezenta, Sum(Solduri.SoldPlati) AS SoldPlati, Sum(Solduri.SoldRetur) AS SoldRetur FROM (SELECT Platitori.IDP, Platitori.si AS SoldInitial, 0 AS SoldPrezenta, 0 AS SoldPlati, 0 AS SoldRetur FROM Platitori WHERE Platitori.si<>0          UNION ALL            SELECT Prezenta.IDP, Sum(0) AS SoldInitial, Sum(Prezenta.ValoareContract) AS SoldPrezenta, Sum(0) AS SoldPlati, (0) AS SoldRetur FROM Prezenta WHERE Prezenta.IDL<[forms]![Prezenta]![IDL] GROUP BY Prezenta.IDP HAVING Sum(Prezenta.ValoareContract)<>0         UNION ALL           SELECT Plati.IDP, Sum(0) AS SoldInitial, Sum(0) AS SoldPrezenta, Sum(Plati.plata) AS SoldPlati, (0) AS SoldRetur FROM Plati WHERE Plati.IDL<[forms]![Prezenta]![IDL] AND Plati.Anulata=False GROUP BY Plati.IDP HAVING Sum(Plati.plata)<>0    UNION ALL           SELECT Retur.IDP, Sum(0) AS SoldInitial, Sum(0) AS SoldPrezenta, Sum(0) AS SoldPlati, Sum(Retur.suma) AS SoldRetur FROM Retur WHERE Retur.IDL<[forms]![Prezenta]![IDL]  AND  Anulat=False GROUP BY Retur.IDP HAVING Sum(Retur.suma)<>0           )  AS Solduri GROUP BY Solduri.IDP)  AS XSolduri RIGHT JOIN Platitori ON XSolduri.IDP = Platitori.IDP) LEFT JOIN (SELECT IDP, Sum(Suma) AS SumaRetur FROM Retur WHERE Anulat=False AND IDL = Forms!prezenta!idl GROUP BY IDP)  AS xRetur ON Platitori.IDP = xRetur.IDP) LEFT JOIN (SELECT IDP, Sum(Plata) AS SumaPlati FROM Plati WHERE Anulata=False AND IDL = Forms!prezenta!idl GROUP BY IDP)  AS xPlati ON Platitori.IDP = xPlati.IDP
GROUP BY Platitori.Nume, Platitori.IDP
ORDER BY Platitori.Nume;
